'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './stripe-flow.css'

export type StripeFlowProps = React.ComponentPropsWithoutRef<'div'> & {
    /** Stripe colour and gap colour. */
    colors?: [string, string]
    /** Stripe width in px. */
    width?: number
    /** Seconds per stripe step. */
    speed?: number
    paused?: boolean
}

// Diagonal stripes gliding along, softened at the edges.
const StripeFlow = ({ colors = ['rgba(167, 139, 250, 0.16)', 'transparent'], width = 22, speed = 1.6, paused = false, className, style, children, ...props }: StripeFlowProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <div
        ref={ref}
        className={['rad-fx-stripes', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-stripe-a': colors[0], '--rad-fx-stripe-b': colors[1], '--rad-fx-stripe-width': `${width}px`, '--rad-fx-stripe-speed': `${speed}s`, ...style } as React.CSSProperties}
        {...props}
    >
        <div className="rad-fx-stripes-layer" aria-hidden="true" />
        <div className="rad-fx-stripes-content">{children}</div>
    </div>
}

export default StripeFlow

.rad-fx-stripes {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.rad-fx-stripes-layer {
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
}

.rad-fx-stripes-content { position: relative; }

.rad-fx-stripes[data-state='paused'] .rad-fx-stripes-layer,
.rad-fx-stripes[data-state='paused'] .rad-fx-stripes-layer * { animation-play-state: paused !important; }

.rad-fx-stripes-layer {
    --rad-fx-stripe-period: calc(var(--rad-fx-stripe-width, 22px) * 2);

    background: repeating-linear-gradient(-45deg, var(--rad-fx-stripe-a) 0 var(--rad-fx-stripe-width, 22px), var(--rad-fx-stripe-b) var(--rad-fx-stripe-width, 22px) var(--rad-fx-stripe-period));
    background-size: calc(var(--rad-fx-stripe-period) * 1.4142) calc(var(--rad-fx-stripe-period) * 1.4142);
    mask-image: radial-gradient(ellipse at center, #000 30%, transparent 80%);
    animation: rad-fx-stripes var(--rad-fx-stripe-speed, 1.6s) linear infinite;
}

@keyframes rad-fx-stripes {
    to { background-position: calc(var(--rad-fx-stripe-period) * 1.4142) 0; }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-stripes-layer { animation: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-stripes-layer { animation: none; }
